"""Alembic migrations must match the models and be reversible."""

from alembic import command
from alembic.config import Config
from alembic.script import ScriptDirectory
from sqlalchemy import Engine, inspect

from app.db.base import Base


def test_migration_history_has_a_single_head(alembic_config: Config) -> None:
    assert len(ScriptDirectory.from_config(alembic_config).get_heads()) == 1


def test_models_match_the_latest_migration(alembic_config: Config, migrated_engine: Engine) -> None:
    # Raises AutogenerateDiffsDetected when a model change has no migration.
    command.check(alembic_config)


def test_downgrade_to_base_and_upgrade_again(
    alembic_config: Config, migrated_engine: Engine
) -> None:
    command.downgrade(alembic_config, "base")
    assert set(inspect(migrated_engine).get_table_names()) == {"alembic_version"}

    command.upgrade(alembic_config, "head")
    tables = set(inspect(migrated_engine).get_table_names())
    assert tables == set(Base.metadata.tables) | {"alembic_version"}
